                p.DurationOfBreakInSec = Configuration.GetSection("Pod:Core:DurationOfBreakInSec").Get<int>();
                p.CircuitBreakerOptions = Configuration.GetSection("Pod:Core:CircuitBreakerOptions").Get<CircuitBreakerOption[]>() ?? Array.Empty<CircuitBreakerOption>();
