"namespace XBank.Mcp.Application.Options;
public class PodOptions
{
    /// <summary>بخش تنظیمات پلتفرم (Pod) که این کلاس از آن بایند می‌شود؛ تنظیمات احراز هویت در <c>Pod:Auth</c> است.</summary>
    public const string SectionName = "Pod:Core";

    public string PlatformServerUrl { get; set; } = string.Empty;
    public int TimeoutInSec { get; set; }
    public int MaxConnectionPerServer { get; set; }
    public int PooledConnectionIdleTimeoutInMin { get; set; }
    public int PooledConnectionLifetimeInMin { get; set; }
    public int RetryCount { get; set; }
    public int AllowedExceptionCountBeforeBreaking { get; set; }
    public int DurationOfBreakInSec { get; set; }
    public bool HttpLoggingEnabled { get; set; }
    public double DefaultTokenMaskedPercentInLog { get; set; }
    public int DefaultResponseBodyLogThreshold { get; set; }
    public string DefaultLogDetailsLevel { get; set; } = string.Empty;
    public object[] HttpLoggingExceptions { get; set; } = Array.Empty<object>();
    public string PreFixAddress { get; set; } = string.Empty;
    
    // Contact paths
    public string AddContactsPath { get; set; } = string.Empty;
    public string TransferToContactPath { get; set; } = string.Empty;
    public string GetContactsByIdPath { get; set; } = string.Empty;
    
    // User paths
    public string GetProfilePath { get; set; } = string.Empty;
    public string GetProfileByAdminPath { get; set; } = string.Empty;
    
    // Billing paths
    public string GetAccountBillPath { get; set; } = string.Empty;
    public string DoServiceCallPath { get; set; } = string.Empty;
    
    // Wallet paths
    public string GetCreditPath { get; set; } = string.Empty;
    public string RequestSettlementByToolPath { get; set; } = string.Empty;
    public string TransferToFollowerPath { get; set; } = string.Empty;
    public string TransferToFollowerForOtherPath { get; set; } = string.Empty;
    public int TransferToFollowerForOtherBusinessId { get; set; }
    public string UserFollowBusinessWMPath { get; set; } = string.Empty;
    
    // Common paths
    public string GetOttPath { get; set; } = string.Empty;
    public string MultiServicesSameTXPath { get; set; } = string.Empty;
    
    // Credit block paths
    public string GetCreditBlockedListPath { get; set; } = string.Empty;
    public string UnblockCreditByHashPath { get; set; } = string.Empty;
    public string BlockCreditByHashcodePath { get; set; } = string.Empty;
    public string ConfirmCreditBlockPath { get; set; } = string.Empty;
    public string GenerateCreditBlockHashCodePath { get; set; } = string.Empty;
    public string TransferByCreditBlockHashPath { get; set; } = string.Empty;
    
    // Multi account paths
    public string GetAccountListPath { get; set; } = string.Empty;
    public string CreateAccountPath { get; set; } = string.Empty;
    public string RegisterAccountInSayyahPath { get; set; } = string.Empty;
    public string TransferToDepositPath { get; set; } = string.Empty;
    public string GetTransferListPath { get; set; } = string.Empty;
    public string IssueInterestDocumentPath { get; set; } = string.Empty;
    public string BankDepositNumber { get; set; } = string.Empty;
    public string ClientId { get; set; } = string.Empty;
    public string ClientSecret { get; set; } = string.Empty;
}
