namespace XBank.Mcp.Api
{
    public class Startup
    {
        public Startup(IConfiguration configuration)
        {
            Configuration = configuration;
        }

        public IConfiguration Configuration { get; }

        public void ConfigureServices(IServiceCollection services)
        {
            services.AddSingleton(Log.Logger);

            services.AddLocalization();

            services.AddProblemDetails(); // Adds standard ProblemDetails support
            services.AddExceptionHandler<GlobalExceptionHandler>(); // Registers your handler

            services.AddCors(options => options.AddPolicy("AllowAll", p => p.AllowAnyOrigin().AllowAnyMethod().AllowAnyHeader()));

            services.AddDbContextPool<McpDbContext>(options =>
            {
                options.EnableSensitiveDataLogging();

                string schemaName = Configuration["db:SchemaName"] ?? "MCP";

                McpDbContext.CurrentSchema = schemaName;

                if (Configuration["db:dbType"] == "SQL")
                {
                    options.UseSqlServer(Configuration["db:sqlConnection"],
                 opt =>
                 {
                     opt.MigrationsAssembly("XBank.Mcp.Infrastructure.EF.SqlMigrations");
                     opt.MigrationsHistoryTable("MigrationsHistory", schemaName);
                     opt.UseQuerySplittingBehavior(QuerySplittingBehavior.SplitQuery);
                 });
                }
                else
                {
                    options.UseOracle(Configuration["db:oracleConnection"],
                        opt =>
                        {
                            opt.MigrationsAssembly("XBank.Mcp.Infrastructure.EF");
                            opt.MigrationsHistoryTable("MigrationsHistory", schemaName);
                            opt.UseQuerySplittingBehavior(QuerySplittingBehavior.SplitQuery);
                        });
                }
            });

            services.AddRepositoryRegistration();
            services.AddFieldMappingServices();
            services.AddScoped<McpAuthentication>();

            services
                .AddHttpClient<IToolExecutor, ToolExecutor>()
                .AddHttpMessageHandler<ClientIpPropagationHandler>()
                .AddXBankHttpLoggingHandler(Configuration.GetSection("HttpClientLogging"), "ToolExecutorLoggingOptions", "HttpLogging");
                //.AddPolicyHandler

            services
                .AddHttpClient<UserAccessTokenService>()
                .AddHttpMessageHandler<ClientIpPropagationHandler>()
                .AddXBankHttpLoggingHandler(Configuration.GetSection("HttpClientLogging"), "ToolExecutorLoggingOptions", "HttpLogging");

            services.AddScoped<ThingTokenService>();
            services.AddScoped<WepodSignatureTokenService>();
            services.AddScoped<EsbSignatureService>();

            services.AddScoped<IWorkflowEngine, WorkflowEngine>();

            services.AddScoped<IToolRegistry, ToolRegistry>();
            services.AddScoped<JsonRpcService>();
            services.AddScoped<SseHandler>();
            services.AddScoped<JsonRpcHandler>();

            services.AddScoped<IAdditionalValues, AdditionalValuesProvider>();
            services.AddScoped<ICurrentRequest, CurrentRequest>();


            services.AddScoped<IStringLocalizer>(sp =>
            {
                var factory = sp.GetRequiredService<IStringLocalizerFactory>();
                return factory.Create("SharedResource", typeof(Program).Assembly.GetName().Name!);
            });

            services.RegisterOptions(Configuration);

            PodOptions podSettings = services.RegisterPodOptions(Configuration);

            // تنظیمات پلتفرم فقط از Pod:Core خوانده می‌شود (همان بخشی که PodOptions به آن بایند شده است)
            services.AddPodPlatform(p =>
            {
                p.PlatformServerUrl = podSettings.PlatformServerUrl;
                p.TimeoutInSec = podSettings.TimeoutInSec;
                p.MaxConnectionPerServer = podSettings.MaxConnectionPerServer;
                p.PooledConnectionIdleTimeoutInMin = podSettings.PooledConnectionIdleTimeoutInMin;
                p.PooledConnectionLifetimeInMin = podSettings.PooledConnectionLifetimeInMin;
                p.RetryCount = podSettings.RetryCount;
                p.AllowedExceptionCountBeforeBreaking = podSettings.AllowedExceptionCountBeforeBreaking;
                p.DurationOfBreakInSec = podSettings.DurationOfBreakInSec;
                p.CircuitBreakerOptions = Configuration.GetSection($"{PodOptions.SectionName}:CircuitBreakerOptions").Get<CircuitBreakerOption[]>() ?? Array.Empty<CircuitBreakerOption>();
            })
            .AddContact(c =>
            {
                c.AddContactsPath = podSettings.AddContactsPath;
                c.TransferToContactPath = podSettings.TransferToContactPath;
                c.GetContactsByIdPath = podSettings.GetContactsByIdPath;
            })
            .AddUser(u =>
            {
                u.GetProfilePath = podSettings.GetProfilePath;
                u.GetProfileByAdminPath = podSettings.GetProfileByAdminPath;
            })
            .AddBilling(b =>
            {
                b.GetAccountBillPath = podSettings.GetAccountBillPath;
                b.DoServiceCallPath = podSettings.DoServiceCallPath;
            })
            .AddWallet(w =>
            {
                w.GetCreditPath = podSettings.GetCreditPath;
                w.RequestSettlementByToolPath = podSettings.RequestSettlementByToolPath;
                w.TransferToFollowerPath = podSettings.TransferToFollowerPath;
                w.TransferToFollowerForOtherPath = podSettings.TransferToFollowerForOtherPath;
                w.TransferToFollowerForOtherBusinessId = podSettings.TransferToFollowerForOtherBusinessId;
                w.UserFollowBusinessWMPath = podSettings.UserFollowBusinessWMPath;
            })
            .AddCommon(c =>
            {
                c.GetOttPath = podSettings.GetOttPath;
                c.MultiServicesSameTXPath = podSettings.MultiServicesSameTXPath;
            })
            .AddCreditBlock(cb =>
            {
                cb.GetCreditBlockedListPath = podSettings.PreFixAddress + podSettings.GetCreditBlockedListPath;
                cb.UnblockCreditByHashPath = podSettings.PreFixAddress + podSettings.UnblockCreditByHashPath;
                cb.BlockCreditByHashcodePath = podSettings.PreFixAddress + podSettings.BlockCreditByHashcodePath;
                cb.ConfirmCreditBlockPath = podSettings.PreFixAddress + podSettings.ConfirmCreditBlockPath;
                cb.GenerateCreditBlockHashCodePath = podSettings.PreFixAddress + podSettings.GenerateCreditBlockHashCodePath;
                cb.TransferByCreditBlockHashPath = podSettings.PreFixAddress + podSettings.TransferByCreditBlockHashPath;
            })
            .AddMultiAccount(c =>
            {
                c.GetAccountListPath = podSettings.PreFixAddress + podSettings.GetAccountListPath;
                c.CreateAccountPath = podSettings.PreFixAddress + podSettings.CreateAccountPath;
                c.RegisterAccountInSayyahPath = podSettings.PreFixAddress + podSettings.RegisterAccountInSayyahPath;
                c.TransferToDepositPath = podSettings.PreFixAddress + podSettings.TransferToDepositPath;
                c.GetTransferListPath = podSettings.PreFixAddress + podSettings.GetTransferListPath;
                c.IssueInterestDocumentPath = podSettings.PreFixAddress + podSettings.IssueInterestDocumentPath;
                c.BankDepositNumber = podSettings.BankDepositNumber;
            })
            .AddXBankHttpLogging(Configuration.GetSection("HttpClientLogging"), "HttpLogging");

            services.AddPodIdentity(p =>
            {
                p.IdentityServerUrl = Configuration["Pod:Auth:AccountServerUrl"];
                p.TimeoutInSec = Configuration.GetSection("Pod:Auth:TimeoutInSec").Get<int>();
                p.MaxConnectionPerServer = Configuration.GetSection("Pod:Auth:MaxConnectionPerServer").Get<int>();
                p.PooledConnectionIdleTimeoutInMin = Configuration.GetSection("Pod:Auth:PooledConnectionIdleTimeoutInMin").Get<int>();
                p.PooledConnectionLifetimeInMin = Configuration.GetSection("Pod:Auth:PooledConnectionLifetimeInMin").Get<int>();
                p.RetryCount = Configuration.GetSection("Pod:Auth:RetryCount").Get<int>();
                p.AllowedExceptionCountBeforeBreaking = Configuration.GetSection("Pod:Auth:AllowedExceptionCountBeforeBreaking").Get<int>();
                p.DurationOfBreakInSec = Configuration.GetSection("Pod:Auth:DurationOfBreakInSec").Get<int>();
                p.CircuitBreakerOptions = Configuration.GetSection("Pod:Auth:CircuitBreakerOptions").Get<CircuitBreakerOption[]>() ?? Array.Empty<CircuitBreakerOption>();
            })
            .AddThing(t =>
            {
                // مسیرهای توکن سرویس Thing از Pod:Auth خوانده می‌شوند؛ اگر کلیدی تنظیم نشده باشد،
                // مقدار پیش‌فرض پکیج حفظ می‌شود تا مسیرها به‌صورت null بازنویسی نشوند.
                ApplyIfConfigured(Configuration["Pod:Auth:CreateTokenPath"], value => t.CreateTokenPath = value);
                ApplyIfConfigured(Configuration["Pod:Auth:GetTokenForThingPath"], value => t.GetTokenForThingPath = value);
                ApplyIfConfigured(Configuration["Pod:Auth:GetThingPath"], value => t.GetThingPath = value);
            })
            .AddAuth()
            .AddXBankHttpLogging(Configuration.GetSection("HttpClientLogging"), "HttpLogging");

            services.AddXBankIdentity(cfg =>
            {
                cfg.DbType = Configuration["Identity:DbType"].ToLower() == "sql" ? DbType.SqlServer : DbType.Oracle;
                cfg.ConnectionString = Configuration["Identity:ConnectionString"];
                cfg.RedisUrl = Configuration["Identity:RedisUrl"];
                cfg.RedisUser = Configuration["Identity:RedisUser"];
                cfg.RedisPassword = Configuration["Identity:RedisPassword"];
                cfg.RedisConnectTimeout = int.Parse(Configuration["Identity:RedisConnectTimeout"]);
                cfg.TokenMaskedPercentInLog = Configuration.GetValue<double>("Identity:TokenMaskedPercentInLog");
                cfg.RedisAbortOnConnectFail = Configuration.GetValue<bool>("Identity:RedisAbortOnConnectFail");
                cfg.RedisDeltaBackoffInMilliseconds = Configuration.GetValue<int>("Identity:RedisDeltaBackoffInMilliseconds");
                cfg.RedisProxy = Configuration.GetValue<string>("Identity:RedisProxy");
                cfg.RedisSyncConnectTimeout = Configuration.GetValue<int>("Identity:RedisSyncConnectTimeout");
                cfg.RedisAsyncConnectTimeout = Configuration.GetValue<int>("Identity:RedisAsyncConnectTimeout");
                cfg.RedisConnectRetry = Configuration.GetValue<int>("Identity:RedisConnectRetry");
                cfg.RedisServiceName = Configuration.GetValue<string>("Identity:RedisServiceName");
                cfg.RedisKeepAlive = Configuration.GetValue<int>("Identity:RedisKeepAlive");
                cfg.RedisTieBreaker = Configuration.GetValue<string>("Identity:RedisTieBreaker");
                cfg.MaxPageSize = Configuration.GetValue<int>("Identity:MaxPageSize");
            },
            cacheOptions =>
            {
                cacheOptions.PodProfileCacheEnabled = bool.Parse(Configuration["Cache:PodProfileCacheEnabled"]);
                cacheOptions.PodProfileCacheExpiryInMinutes = int.Parse(Configuration["Cache:PodProfileCacheExpiryInMinutes"]);
                cacheOptions.MemoryCacheSize = int.Parse(Configuration["Cache:MemoryCacheSize"]);
                cacheOptions.ClientAbsoluteExpiry = TimeSpan.Parse(Configuration["Cache:ClientAbsoluteExpiry"]);
                cacheOptions.ClientSlidingExpiry = TimeSpan.Parse(Configuration["Cache:ClientSlidingExpiry"]);
                cacheOptions.ClientMappingAbsoluteExpiry = TimeSpan.Parse(Configuration["Cache:ClientMappingAbsoluteExpiry"]);
                cacheOptions.ClientMappingSlidingExpiry = TimeSpan.Parse(Configuration["Cache:ClientMappingSlidingExpiry"]);
            },
            Configuration)
                .AddXBankAuthentication()
                .AddXBankThingAuthentication()
                .AddXBankSignatureAuthentication(options =>
                {
                    options.TimestampToleranceSeconds = int.Parse(Configuration["Identity:SignatureAuthTimestampToleranceSeconds"]);
                });

            services.AddMediatR(typeof(ApplicationAssembly));

            services.AddScoped<IMcpToolCaller, McpToolCaller>();

            if(bool.Parse(Configuration["McpQueueOptions:Enabled"]))
            {
                services.AddRabbitMqServices(options =>
                {
                    Configuration.GetSection("Rabbit").Bind(options);
                });

                services.AddActiveMqServices(mcpQueueOptions =>
                {
                    mcpQueueOptions.Hosts = Configuration["McpQueueOptions:Hosts"];
                    mcpQueueOptions.Port = Configuration.GetValue<int>("McpQueueOptions:Port");
                    mcpQueueOptions.Username = Configuration["McpQueueOptions:Username"];
                    mcpQueueOptions.Password = Configuration["McpQueueOptions:Password"];
                    mcpQueueOptions.PrefetchSize = int.TryParse(Configuration["McpQueueOptions:PrefetchSize"], out int size) ? size : 1;
                    mcpQueueOptions.IncomingQueue = Configuration["McpQueueOptions:IncomingQueue"];
                    mcpQueueOptions.OutgoingQueue = Configuration["McpQueueOptions:OutgoingQueue"];
                    mcpQueueOptions.ServerName = Configuration["McpQueueOptions:ServerName"];
                    mcpQueueOptions.UseInMemory = bool.Parse(Configuration["McpQueueOptions:UseInMemory"]);
                    mcpQueueOptions.RetryInterval = int.TryParse(Configuration["McpQueueOptions:RetryInterval"], out int delay) ? delay : 0;
                    mcpQueueOptions.RetryCounts = int.TryParse(Configuration["McpQueueOptions:RetryCounts"],out int retry) ? retry : 3;
                    mcpQueueOptions.ConcurrentMessageLimit = int.TryParse(Configuration["McpQueueOptions:ConcurrentMessageLimit"],out int con) ? con : 5;
                });
            }

            services.RegisterClients(Options =>
            {
                Options.ClientTimeoutInSec = int.Parse(Configuration["XBankClients:ClientTimeoutInSec"]);
                Options.MockEnabled = Configuration.GetValue<bool?>("XBankClients:MockEnabled");
                Options.ThirdParty = new ThirdPartyOptions
                {
                    BaseUrl = Configuration["XBankClients:ThirdParty:BaseUrl"],
                    ApiKey = Configuration["XBankClients:ThirdParty:ApiKey"],
                    PrivateKey = Configuration["XBankClients:ThirdParty:PrivateKey"],
                    GetMcpThreadPath = Configuration["XBankClients:ThirdParty:GetMcpThreadPath"]
                };
            }).AddXBankHttpLogging(opt =>
            {
                opt.HttpLoggingEnabled = Configuration.GetValue<bool>("XBankClients:Logging:HttpLoggingEnabled");
                opt.LogResponseBodyOnlyOnFailure = Configuration.GetValue<bool>("XBankClients:Logging:LogResponseBodyOnlyOnFailure");
                opt.DefaultLogDetailsLevel = Configuration.GetValue<Shared.Log.LogDetailsLevel>("XBankClients:Logging:DefaultLogDetailsLevel");
                opt.DefaultResponseBodyLogThreshold = int.Parse(Configuration["XBankClients:Logging:DefaultResponseBodyLogThreshold"]);
                opt.Exceptions = Configuration.GetSection("XBankClients:Logging:Exceptions").Get<Shared.Log.LoggingExceptionsOptions[]>() ?? Array.Empty<Shared.Log.LoggingExceptionsOptions>();
                opt.FieldsToMaskInRequestBody = Configuration.GetSection("XBankClients:Logging:FieldsToMaskInRequestBody").Get<List<string>>() ?? new List<string>();
            });;

            services.AddValidatorsFromAssembly(typeof(ApplicationAssembly).Assembly);
            services.AddTransient(typeof(IPipelineBehavior<,>), typeof(ValidationBehavior<,>));

            services.AddControllers();

            services.AddEndpointsApiExplorer();
            services.AddSwaggerGen(options =>
            {
                options.SwaggerDoc("v1", new Microsoft.OpenApi.Models.OpenApiInfo
                {
                    Title = "XBank MCP API",
                    Version = "v1"
                });
            });
            

            services.AddMcpAuthentication();

            services.AddScoped<IJwtTokenService, JwtTokenService>();
            services.AddSingleton<SseConnectionManager>();
            services.AddUserHeadersDelegatingHandler();
            services.AddClientIpPropagationHandler();

            services.AddSingleton(typeof(IMcpRedisStore<>), typeof(McpRedisStore<>));

            services.AddKeyedSingleton<IConnectionMultiplexer>("McpRedis", (sp, key) =>
            {
                IOptions<RedisOptions> redisOptions = sp.GetRequiredService<IOptions<RedisOptions>>();
                return ConnectionMultiplexer.Connect(redisOptions.Value.ToConfigurationOptions());
            });

            //Because Oauth.RedisStore is registered as Scoped
            services.AddScoped(typeof(IMcpOauthCodeMappingCacheService), typeof(McpOauthCodeMappingCacheService));

            services.AddHeaderMasker(options =>
            {
                List<string> headers = Configuration.GetSection("SensitiveHeaders:SensitiveHeaders").Get<List<string>>() ?? new List<string>();
                options.SensitiveHeaders = headers;
                options.MaskPercentage = double.Parse(Configuration["SensitiveHeaders:MaskPercentage"], CultureInfo.InvariantCulture);
            });

            services.Configure<ForwardedHeadersOptions>(options =>
            {
                options.ForwardLimit = null;

                options.KnownProxies.Clear();
                options.KnownNetworks.Clear();

                options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
            });

            services.AddHealthChecks()
                .AddDbContextCheck<McpDbContext>(name: "Database", tags: new[] { "ready" })
                .AddRedis($"{Configuration["Redis:Endpoint"]},user={Configuration["Redis:User"]},password={Configuration["Redis:Password"]},resolveDns=True", name: "Mcp Redis", tags: new[] { "ready" })
                .AddRedis($"{Configuration["Identity:RedisUrl"]},user={Configuration["Identity:RedisUser"]},password={Configuration["Identity:RedisPassword"]},resolveDns=True", name: "Shared Redis", tags: new[] { "ready" });
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            app.UseExceptionHandler();

            // NSwag و Swashbuckle هر دو UseSwagger دارند؛ چون NSwag.AspNetCore هنوز رفرنس است، صریح صدا میزنیم
            SwaggerBuilderExtensions.UseSwagger(app);
            app.UseSwaggerUI(options => options.SwaggerEndpoint("/swagger/v1/swagger.json", "XBank MCP API v1"));

            var useHttps = Configuration.GetValue<bool>("UseHttpsRedirection");
            if (useHttps)
                app.UseHttpsRedirection();

            //todo
            app.UseCors("AllowAll");

            app.UseForwardedHeaders();

            app.UseMiddleware<BeforeAuthenticationLogMiddleware>();

            var environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT");
            if (environment.Equals("STAGING", StringComparison.CurrentCultureIgnoreCase))
            {
                app.UseSseJsonRpc();
            }

            if (env.IsDevelopment())
            {
                app.UseOpenApi();
                app.UseSwaggerUi3(options =>
                {
                    options.EnableTryItOut = true;
                });
            }

            app.UseRouting();

            app.UseAuthentication();
            app.UseAuthorization();

            app.UseMiddleware<RequestResponseLoggingMiddleware>();

            Console.OutputEncoding = Encoding.UTF8;

            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
                endpoints.MapHealthChecks("api/health", new HealthCheckOptions()
                {
                    ResponseWriter = UIResponseWriter.WriteHealthCheckUIResponse
                })
                .RequireAuthorization(PolicyKeys.HealthCheckAdmin);
            });
        }
    }
}
